            pos = traitType.getSelectedItemPosition() + 1;

            if (pos > traitType.getCount() - 1) {
                pos = 0;

                if (parent.is_cycling_traits_advances())
                    rangeBox.clickRight();
            }
        }

        traitType.setSelection(pos);
    }

