/**
 * Adds the given step to the current counter value and saves it.
 * Does nothing when no trait is currently selected, which happens
 * when the loaded field has no (visible) traits associated with it.
 */
private void updateCounter(int step) {
    final TraitObject currentTrait = getCurrentTrait();

    if (currentTrait == null) {
        return;
    }

    final String traitName = currentTrait.getTrait();
    final Object currentValue = getNewTraits().get(traitName);

    if (currentValue != null && currentValue.toString().equals("NA")) {
        counterTv.setText(Integer.toString(step));
    } else {
        counterTv.setText(Integer.toString(getCounterValue() + step));
    }

    updateTrait(traitName, "counter", counterTv.getText().toString());
}

private int getCounterValue() {
    try {
        return Integer.parseInt(counterTv.getText().toString());
    } catch (NumberFormatException e) {
        return 0;
    }
}

